	if (description3 != NULL)
		m_description[2] = _strdup(description3, "fts_missioncam.cpp", 59);

	m_anim = ZAnim.GetAnim(animation, NULL);

	if (music != NULL)
		m_music = CSnd::GetSoundByName(music);
